<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {connectAccountingNotifications} from './notificationRealtime';
const props=defineProps<{company?:number|null;csrf?:string}>();
const enabled=ref(false),open=ref(false),data=ref<any>(null),loading=ref(false),busy=ref(false),error=ref(''),live=ref('connecting'),bell=ref<HTMLElement|null>(null),panel=ref<HTMLElement|null>(null),position=ref<Record<string,string>>({});
let closed=false,generation=0,disconnect:(()=>void)|undefined,pending=false,refreshing=false;
function query(before?:number){const q=new URLSearchParams();if(props.company)q.set('company_id',String(props.company));if(before)q.set('before_id',String(before));return q.toString();}
async function load(more=false){const gen=++generation;if(!more)loading.value=true;error.value='';try{const items=data.value?.items||[];const before=more?items[items.length-1]?.id:undefined;const response=await fetch('/accounting/api/notifications?'+query(before),{headers:{Accept:'application/json'}});if(response.status===403){enabled.value=false;open.value=false;disconnect?.();return;}const result=await response.json();if(!response.ok)throw Error(result.message||'Unable to load notifications.');if(closed||gen!==generation)return;data.value={...result,items:more?[...(data.value?.items||[]),...result.items]:result.items};enabled.value=Array.isArray(result.items);}catch(e){if(!closed&&gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
async function refresh(){pending=true;if(refreshing)return;refreshing=true;try{while(pending&&!closed){pending=false;await load();}}finally{refreshing=false;}}
function place(){const r=bell.value?.getBoundingClientRect();if(!r)return;const width=Math.min(350,innerWidth-24);position.value={width:width+'px',left:Math.max(12,Math.min(r.right-width,innerWidth-width-12))+'px',top:Math.max(12,Math.min(r.bottom+8,innerHeight-180))+'px',maxHeight:(innerHeight-Math.max(12,Math.min(r.bottom+8,innerHeight-180))-12)+'px'};}
async function toggle(){open.value=!open.value;if(open.value){place();await refresh();await nextTick();panel.value?.querySelector<HTMLElement>('button,a')?.focus();}}
function outside(e:PointerEvent){if(!(e.target instanceof Node))return;if(!bell.value?.contains(e.target)&&!panel.value?.contains(e.target))open.value=false;}
function escape(e:KeyboardEvent){if(e.key==='Escape'&&open.value){open.value=false;bell.value?.focus();}}
function scroll(e:Event){if(open.value&&e.target instanceof Node&&!panel.value?.contains(e.target))open.value=false;}
async function read(item?:any){if(busy.value)return;busy.value=true;error.value='';try{const body={...(props.company?{company_id:props.company}:{}),...(item?{id:item.id}:{through_id:data.value?.latest_id||0})};const response=await fetch('/accounting/api/notifications/read',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(body)});if(!response.ok)throw Error('Unable to mark notifications as read.');await refresh();if(item){open.value=false;if(item.url){const target=new URL(item.url,location.origin);const sameDocument=target.pathname===location.pathname&&target.search===location.search;location.assign(target.href);if(sameDocument)location.reload();}}}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
watch(()=>props.company,()=>{generation++;data.value=null;open.value=false;void refresh();});
onMounted(async()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);window.addEventListener('resize',place);window.addEventListener('scroll',scroll,true);await refresh();if(!closed&&enabled.value)disconnect=connectAccountingNotifications(()=>props.csrf||'',()=>void refresh(),state=>live.value=state);});
onBeforeUnmount(()=>{closed=true;generation++;disconnect?.();document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);window.removeEventListener('resize',place);window.removeEventListener('scroll',scroll,true);});
useAccountingAlerts(error);
</script>
<template><div v-if="enabled" class="acn-notifications"><button ref="bell" type="button" class="acn-bell" aria-label="Accounting notifications" :aria-expanded="open" aria-controls="accounting-notification-panel" @click="toggle"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span v-if="data?.unread_count" class="acn-count" aria-live="polite">{{data.unread_count>99?'99+':data.unread_count}}</span></button>
<Teleport to="body"><section v-if="open" id="accounting-notification-panel" ref="panel" class="acn-panel" :style="position" role="region" aria-label="Accounting activity notifications"><header><div><h3>Accounting activity</h3><small><i :class="live"></i>{{live==='live'?'Live updates':live==='connecting'?'Connecting':live==='disabled'?'Live updates disabled':live==='reconnecting'?'Reconnecting':'Connection unavailable'}}</small></div><button type="button" class="acn-close" aria-label="Close notifications" @click="open=false;bell?.focus()">&times;</button></header><div class="acn-toolbar"><span>{{data?.unread_count||0}} unread</span><button type="button" :disabled="busy||!data?.unread_count" @click="read()">Mark all read</button></div><p v-if="error" class="acn-error" role="alert">{{error}}</p><div class="acn-items" :aria-busy="loading"><p v-if="loading&&!data" class="acn-empty">Loading activity...</p><p v-else-if="!data?.items?.length" class="acn-empty">No activity from other people yet.</p><button v-for="item in data?.items||[]" :key="item.id" :title="[item.actor_name,item.title,item.subject,item.company_name,new Date(item.created_at).toLocaleString()].join(' | ')" type="button" class="acn-item" :class="{unread:!item.read_at}" :disabled="busy" @click="read(item)"><span class="acn-avatar" aria-hidden="true">{{item.actor_name?.slice(0,1)}}</span><span><strong>{{item.actor_name}}</strong><span class="acn-action">{{item.title}}</span><span class="acn-subject">{{item.subject}}</span><small>{{item.company_name}} &middot; {{new Date(item.created_at).toLocaleString()}}</small></span><i v-if="!item.read_at" class="acn-unread-dot" aria-label="Unread"></i></button></div><footer v-if="data?.has_more"><button type="button" :disabled="loading||busy" @click="load(true)">Show older activity</button></footer></section></Teleport></div></template>
<style scoped>
.acn-notifications{flex:none}.acn-bell{position:relative;display:flex;align-items:center;justify-content:center;width:40px;height:40px;padding:9px;border:1px solid var(--line);border-radius:9px;background:var(--rail);color:var(--text);cursor:pointer}.acn-bell svg{width:20px;height:20px}.acn-count{position:absolute;top:-7px;right:-7px;border:2px solid var(--bg);border-radius:12px;background:#7665ed;color:#fff;font-size:10px;line-height:16px;min-width:20px;padding:0 4px;font-weight:700}.acn-panel{position:fixed;z-index:1000;border:1px solid var(--line);border-radius:14px;background:var(--bg);color:var(--text);box-shadow:0 16px 48px #0003;overflow:hidden;max-height:calc(100dvh - 140px);display:flex;flex-direction:column}.acn-panel header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--line)}.acn-panel h3{margin:0 0 7px;font-size:15px}.acn-panel header small{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--muted)}.acn-panel header i{width:6px;height:6px;border-radius:50%;background:#d59931}.acn-panel header i.live{background:#22b573}.acn-close{border:0;background:none;color:var(--muted);font-size:25px;cursor:pointer;padding:2px 5px}.acn-toolbar{display:flex;justify-content:space-between;align-items:center;padding:11px 20px;background:var(--rail);font-size:11px;color:var(--muted)}.acn-toolbar button,.acn-panel footer button{border:0;background:none;color:#7665ed;font:inherit;font-size:11px;cursor:pointer}.acn-panel button:disabled{cursor:default;opacity:.6}.acn-items{overflow:auto;min-height:0;overscroll-behavior:contain}.acn-item{display:flex;text-align:left;gap:12px;padding:16px 20px;width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--text);font:inherit;cursor:pointer}.acn-item:hover{background:var(--rail)}.acn-item.unread{background:color-mix(in srgb,#7665ed 5%,var(--bg))}.acn-avatar{display:flex;align-items:center;justify-content:center;width:32px;height:32px;flex:0 0 32px;border-radius:10px;background:color-mix(in srgb,#7665ed 12%,transparent);color:#7665ed;font-size:12px;font-weight:700}.acn-item>span:nth-child(2){min-width:0;flex:1}.acn-item strong{display:block;font-size:12px}.acn-action{display:block;font-size:12px;margin-top:4px;line-height:1.5}.acn-subject{display:block;font-size:11px;margin-top:4px;color:var(--muted);overflow-wrap:anywhere}.acn-item small{display:block;font-size:10px;color:var(--muted);margin-top:7px;line-height:1.6}.acn-unread-dot{width:6px;height:6px;flex:0 0 6px;border-radius:50%;background:#7665ed;margin-top:6px}.acn-empty{padding:32px 20px;margin:0;font-size:12px;color:var(--muted);text-align:center}.acn-error{font-size:12px;padding:10px 20px;color:#da5252}.acn-panel footer{padding:13px;text-align:center;background:var(--rail)}

.acn-panel{border-radius:10px}.acn-panel header{padding:11px 14px;flex-shrink:0}.acn-panel h3{font-size:13px;margin-bottom:4px}.acn-toolbar{padding:8px 14px;flex-shrink:0}.acn-items{max-height:440px;flex:0 1 auto;scrollbar-width:thin}.acn-item{height:88px;box-sizing:border-box;gap:9px;padding:10px 12px;align-items:flex-start}.acn-avatar{width:26px;height:26px;flex-basis:26px;border-radius:7px;font-size:11px}.acn-item strong,.acn-action,.acn-subject,.acn-item small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:15px}.acn-item strong{font-size:11px}.acn-action{font-size:11px;margin-top:1px}.acn-subject{font-size:10px;margin-top:1px}.acn-item small{font-size:9px;margin-top:3px}.acn-panel footer{padding:9px;flex-shrink:0}
</style>
